import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate } from 'react-router-dom'; 
import "./RiverDashboard.css";

const DEBUG_API = "http://127.0.0.1:8000/api/weather/debug-read-s3";

const RiverDashboard = () => {
  const navigate = useNavigate();
  
  // --- STATE ---
  const [forecastData, setForecastData] = useState([]);
  const [limeData, setLimeData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [lastUpdated, setLastUpdated] = useState("");
  const [currentTime, setCurrentTime] = useState(new Date());

  // --- HELPERS ---
  const getStatus = (level) => {
    const val = parseFloat(level);
    if (val < 5.5) return { label: "Normal", class: "status-normal", color: "#10b981", icon: "fa-check" }; 
    if (val < 6.0) return { label: "Caution", class: "status-caution", color: "#f59e0b", icon: "fa-exclamation" }; 
    return { label: "Warning", class: "status-critical", color: "#ef4444", icon: "fa-bell" }; 
  };

  // --- EFFECTS ---
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    const fetchForecast = async () => {
      try {
        const response = await axios.get(DEBUG_API, { params: { file: "forecast_output.csv" } });
        if (response.data.status === "success") {
          const rawLines = response.data.preview;
          const parsedData = rawLines.slice(1).map((line) => {
              const cols = line.split(",");
              const level = cols[cols.length - 1]?.trim();
              return { level: parseFloat(level).toFixed(2), status: getStatus(level) };
            }).filter((item) => !isNaN(item.level));
          setForecastData(parsedData);
          setLastUpdated(new Date().toLocaleTimeString("en-US", {hour: '2-digit', minute:'2-digit'}));
        }
      } catch (err) {
        console.error("Forecast API error:", err);
        setError("Failed to fetch forecast data");
      }
    };

    const fetchLimeInsights = async () => {
      try {
        const response = await axios.get(DEBUG_API, { params: { file: "lime_short_sentences_and_labels.txt" } });
        if (response.data.status === "success") {
          setLimeData(response.data.preview);
        }
      } catch (err) {
        console.error("LIME API error:", err);
      }
    };

    const loadAllData = async () => {
      setLoading(true);
      await Promise.all([fetchForecast(), fetchLimeInsights()]);
      setLoading(false);
    };

    loadAllData();
  }, []);

  const nextHour = forecastData[0] || { level: "--", status: getStatus(0) };
  const currentLevel = (parseFloat(nextHour.level) - 0.17).toFixed(2);
  const currentStatus = getStatus(currentLevel);

  if (loading) return <div className="rd-loading"><div className="rd-spinner"></div><p>Connecting to Kalady Station...</p></div>;
  if (error && forecastData.length === 0) return <div className="rd-error"><h3>Signal Lost</h3><p>{error}</p></div>;

  return (
    <div className="rd-container">
      
      {/* --- TOP NAVIGATION --- */}
      <nav className="rd-navbar">
        <div className="rd-wrapper rd-flex-between">
          <div className="rd-logo">
            <div className="logo-icon"><i className="fas fa-water"></i></div>
            <div className="logo-text">
              <h3>Periyar<span>Sense</span></h3>
              <small>MeitY & ASIET Initiative</small>
            </div>
          </div>
          <div className="rd-nav-items">
            <button onClick={() => navigate('/')}>Home</button>
            <button className="active">Dashboard</button>
            <button onClick={() => navigate('/weather-map')}>Map View</button>
            <div className="rd-clock">
              {currentTime.toLocaleTimeString('en-IN', {hour: '2-digit', minute:'2-digit'})}
            </div>
          </div>
        </div>
      </nav>

      <main className="rd-main rd-wrapper">
        
        {/* --- SECTION 1: HERO CONTROL CARD --- */}
        <div className="rd-hero-card">
          <div className="rd-hero-bg"></div>
          <div className="rd-hero-overlay">
            <div className="rd-hero-left">
              <span className="live-badge"><span className="pulse-dot"></span> Live Monitoring</span>
              <h1>Kalady Station</h1>
              <p>Real-time water level data processed by AI causality models.</p>
              
              <div className="rd-big-stat">
                <span className="stat-value">{currentLevel}</span>
                <span className="stat-unit">meters</span>
              </div>
              <div className="stat-sub">Updated: {lastUpdated}</div>
            </div>

            <div className="rd-hero-right">
              <div className={`status-box ${currentStatus.class}`}>
                <div className="icon-circle">
                  <i className={`fas ${currentStatus.icon}`}></i>
                </div>
                <div>
                  <h4>Current Status</h4>
                  <h2>{currentStatus.label}</h2>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* --- SECTION 2: GRID LAYOUT --- */}
        <div className="rd-grid">
          
          {/* --- LEFT: FORECAST VISUALS --- */}
          <div className="rd-grid-left">
            
            {/* 1-Hour Card */}
            <div className="rd-panel mini-panel">
              <div className="panel-head">
                <span><i className="fas fa-clock"></i> Next Hour (H+1)</span>
                <span className="conf-badge">98.5% Conf.</span>
              </div>
              <div className="mini-stat-row">
                <div className="val" style={{color: nextHour.status.color}}>{nextHour.level}m</div>
                <div className="trend">
                  {parseFloat(nextHour.level) > parseFloat(currentLevel) ? 
                    <span className="rising"><i className="fas fa-arrow-up"></i> Rising</span> : 
                    <span className="falling"><i className="fas fa-arrow-down"></i> Falling</span>}
                </div>
              </div>
            </div>

            {/* 6-Hour Chart Panel */}
            <div className="rd-panel chart-panel">
              <div className="panel-head">
                <span><i className="fas fa-chart-bar"></i> 6-Hour Projection</span>
              </div>
              <div className="rd-bars-container">
                {forecastData.slice(0, 6).map((data, index) => (
                  <div key={index} className="rd-bar-group">
                    <div className="bar-val">{data.level}m</div>
                    <div className="bar-track">
                      <div 
                        className="bar-fill" 
                        style={{
                          height: `${(data.level/8)*100}%`,
                          backgroundColor: data.status.color,
                          boxShadow: `0 0 10px ${data.status.color}40`
                        }}
                      ></div>
                    </div>
                    <div className="bar-label">H+{index+1}</div>
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* --- RIGHT: AI TIMELINE (Full Height) --- */}
          <div className="rd-grid-right">
            <div className="rd-panel ai-panel">
              <div className="panel-head">
                <span><i className="fas fa-brain"></i> AI Causality Insights</span>
                <span className="live-indicator">Processing...</span>
              </div>
              
              <div className="rd-timeline-feed">
                {limeData.length > 0 ? (
                  limeData.slice(0, 6).map((line, index) => {
                    const color = forecastData[index]?.status?.color || "#ccc";
                    return (
                      <div key={index} className="timeline-item">
                        <div className="timeline-left">
                          <div className="t-time">H+{index+1}</div>
                          <div className="t-line"></div>
                          <div className="t-dot" style={{borderColor: color, background: color}}></div>
                        </div>
                        <div className="timeline-content" style={{borderLeftColor: color}}>
                          <p>{line}</p>
                        </div>
                      </div>
                    );
                  })
                ) : (
                  <div className="empty-state">Model initializing...</div>
                )}
              </div>
            </div>
          </div>

        </div>
      </main>
      
      <footer className="rd-footer">
        &copy; 2026 Adi Shankara Institute • Ministry of Earth Sciences • Government of India
      </footer>
    </div>
  );
};

export default RiverDashboard;
